my $file='/app/sequences.fasta';
open my $fh,'<',$file or die $!;
my %seq; my $id;
while(<$fh>){chomp; if(/^>(\S+)/){$id=$1; next;} next unless defined $id; s/\s+//g; $seq{$id}.=lc($_);} 
my $out=$seq{output};
# find insertion
my $pref=0; my $in=$seq{input};
for my $i (0..length($in)-1){ if(substr($in,$i,1) eq substr($out,$i,1)){$pref=$i+1;} else {last;} }
my $suff=0; for my $i (0..length($in)-1){ if(substr($in,length($in)-1-$i,1) eq substr($out,length($out)-1-$i,1)){$suff=$i+1;} else {last;} }
my $insert=substr($out,$pref,length($out)-$pref-$suff);
print "insert len ",length($insert),"\n";
for my $k (qw(egfp flag snap)){
  my $a=$seq{$k};
  my $b=$insert;
  my $la=length($a); my $lb=length($b);
  my @prev=(0)x($lb+1); my @curr;
  my ($best,$best_i,$best_j)=(0,0,0);
  for my $i (1..$la){
    @curr=(0)x($lb+1);
    my $ca=substr($a,$i-1,1);
    for my $j (1..$lb){
      if($ca eq substr($b,$j-1,1)){
        $curr[$j]=$prev[$j-1]+1;
        if($curr[$j]>$best){$best=$curr[$j]; $best_i=$i; $best_j=$j;}
      }
