my $flag_f_primer=build_fwd($oh_eg_flag,$flag_f_seq);
my $flag_r_primer=build_rev($oh_flag_snap,$flag_r_seq);
my $snap_f_primer=build_fwd($oh_flag_snap,$snap_f_seq);
my $snap_r_primer=build_rev($oh_snap_input,$snap_r_seq);

