print "Tm differences: input ",abs($input_f_tm-$input_r_tm)," egfp ",abs($eg_f_tm-$eg_r_tm)," flag ",abs($flag_f_tm-$flag_r_tm)," snap ",abs($snap_f_tm-$snap_r_tm),"\n";

print "final primers:\n";
