while(<$fh>){chomp; if(/^>(\S+)/){$id=$1; next;} next unless defined $id; s/\s+//g; $seq{$id}.=lc($_);} 
my $in=$seq{input}; my $out=$seq{output};
# compute prefix and suffix
my $pref=0; for my $i (0..length($in)-1){ if(substr($in,$i,1) eq substr($out,$i,1)){$pref=$i+1;} else {last;} }
my $suff=0; for my $i (0..length($in)-1){ if(substr($in,length($in)-1-$i,1) eq substr($out,length($out)-1-$i,1)){$suff=$i+1;} else {last;} }
